Image *ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception) {
    Image *image = NULL;

    if (!image_info || !exception)
        return NULL;

    /* Open the image file */
    FILE *file = fopen(image_info->filename, "rb");
    if (!file) {
        ThrowFileException(exception, FileOpenError, "Unable to open", image_info->filename);
        return NULL;
    }

    /* Check for valid PNG signature */
    unsigned char signature[8];
    if (fread(signature, 1, 8, file) != 8 || memcmp(signature, "\x89PNG\r\n\x1a\n", 8) != 0) {
        fclose(file);
        Throw(exception, CorruptImageError, "Invalid PNG signature");
        return NULL;
    }

    /* Allocate memory for MngInfo and read image data */
    MngInfo *mng_info = (MngInfo *) AcquireMemory(sizeof(MngInfo));
    if (!mng_info) {
        fclose(file);
        return NULL;
    }

    InitializeMngInfo(mng_info, file, image_info, exception);

    /* Read the PNG data and create the image */
    image = ReadPNGImageData(mng_info, file, exception);
    if (!image) {
        DestroyMngInfo(mng_info);
        fclose(file);
        return NULL;
    }

    /* Check and adjust the colorspace if necessary */
    if (image->colorspace == UndefinedColorspace) {
        if (mng_info->colorspace != UndefinedColorspace)
            image->colorspace = mng_info->colorspace;
        else
            image->colorspace = sRGBColorspace;
    }

    /* Cleanup and return */
    DestroyMngInfo(mng_info);
    fclose(file);
    return image;
}

Image *ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception) {
  Image *image = NULL;
  FILE *file = NULL;
  MngInfo *mng_info = NULL;

  // Validate input parameters
  if (!image_info || !exception)
    return NULL;

  // Open image file
  file = fopen(image_info->filename, "rb");
  if (!file)
    return NULL;

  // Check PNG signature
  unsigned char signature[PNGSIG_BYTES];
  if (fread(signature, sizeof(*signature), PNGSIG_BYTES, file) != PNGSIG_BYTES) {
    fclose(file);
    return NULL;
  }

  if (png_sig_cmp(signature, 0, PNGSIG_BYTES)) {
    fclose(file);
    ThrowException(exception, OptionError, "InvalidPngSignature", image_info->filename);
    return NULL;
  }

  // Allocate and initialize MngInfo
  mng_info = AcquireMngInfo();
  if (!mng_info) {
    fclose(file);
    return NULL;
  }

  // Read PNG image data
  image = ReadPNGImageInternal(file, mng_info, image_info, exception);
  if (!image) {
    fclose(file);
    ReleaseMngInfo(mng_info);
    return NULL;
  }

  // Adjust colorspace if necessary
  if (image->colorspace == UndefinedColorspace)
    image->colorspace = sRGBColorspace;

  // Close file and release resources
  fclose(file);
  ReleaseMngInfo(mng_info);

  return image;
}

Image *
ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image;
  FILE *file;
  MngInfo *mng_info;
  unsigned char signature[PNGSIG_CHUNK_SIZE];
  size_t length;

  assert(image_info != (ImageInfo *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  (void) LogMagickEvent(CoderEvent, GetMagickModule(), "Enter ReadPNGImage()");

  image = NULL;
  file = fopen(image_info->filename, "rb");
  if (file == (FILE *) NULL)
  {
    (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError,
      "Unable to open file", "%s", image_info->filename);
    return (Image *) NULL;
  }

  length = fread(signature, sizeof(*signature), PNGSIG_CHUNK_SIZE, file);
  if (length != PNGSIG_CHUNK_SIZE)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "Not enough data in file", "%s", image_info->filename);
    return (Image *) NULL;
  }

  if (!IsPNGSignature(signature))
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "Not a PNG image", "%s", image_info->filename);
    return (Image *) NULL;
  }

  mng_info = (MngInfo *) AcquireMagickMemory(sizeof(*mng_info));
  if (mng_info == (MngInfo *) NULL)
  {
    (void) fclose(file);
    (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
      "Unable to allocate MngInfo structure", "(%s)", image_info->filename);
    return (Image *) NULL;
  }

  (void) memset(mng_info, 0, sizeof(*mng_info));

  if (!ReadPNGImageData(file, image_info, mng_info, &image, exception))
  {
    (void) fclose(file);
    (void) RelinquishMagickMemory(mng_info);
    return (Image *) NULL;
  }

  (void) fclose(file);

  if ((image->columns == 0) || (image->rows == 0))
  {
    (void) DestroyImageList(image);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "Width or height is zero", "%s", image_info->filename);
    return (Image *) NULL;
  }

  if (image->colorspace == UndefinedColorspace)
    image->colorspace = sRGBColorspace;

  (void) LogMagickEvent(CoderEvent, GetMagickModule(), "Leave ReadPNGImage()");
  return image;
}

Image *ReadPNGImage(const ImageInfo *image_info, ExceptionInfo *exception) {
    Image *image = NULL;
    FILE *file = NULL;

    if ((image_info == NULL) || (exception == NULL))
        return NULL;

    LogMagickEvent(CoderEvent, "Entering ReadPNGImage");

    file = fopen(image_info->filename, "rb");
    if (file == NULL) {
        ThrowFileException(exception, FileOpenError, image_info->filename, image_info->filename);
        return NULL;
    }

    uint8_t signature[PNG_SIG_SIZE];
    if (fread(signature, PNG_SIG_SIZE, 1, file) != 1) {
        fclose(file);
        ThrowFileException(exception, CorruptImageError, "ImproperImageFile", image_info->filename);
        return NULL;
    }

    if (memcmp(signature, "\211PNG\r\n\032\n", PNG_SIG_SIZE) != 0) {
        fclose(file);
        ThrowFileException(exception, CorruptImageError, "NotPNGFile", image_info->filename);
        return NULL;
    }

    MngInfo *mng_info = (MngInfo *) AcquireMemory(sizeof(MngInfo));
    if (mng_info == NULL) {
        fclose(file);
        return NULL;
    }

    memset(mng_info, 0, sizeof(MngInfo));
    mng_info->file = file;

    image = ReadImage(image_info, file, mng_info, exception);
    if (image == NULL) {
        RelinquishMemory(mng_info);
        fclose(file);
        return NULL;
    }

    if (image->columns == 0 || image->rows == 0) {
        DestroyImageList(image);
        RelinquishMemory(mng_info);
        fclose(file);
        ThrowFileException(exception, CorruptImageError, "InvalidImageSize", image_info->filename);
        return NULL;
    }

    if (image->colorspace == UndefinedColorspace)
        image->colorspace = RGBColorspace;

    LogMagickEvent(CoderEvent, "Exiting ReadPNGImage");

    return image;
}

